    if (countB1 > 0) changedSummary.push(`B1(Flag 2) [${Object.keys(modifiedB1).join(",")}]`);
    if (countB2 > 0) changedSummary.push(`B2(Flag 4) [${Object.keys(modifiedB2).join(",")}]`);
    if (countB3 > 0) changedSummary.push(`B3(Flag 8) [${Object.keys(modifiedB3).join(",")}]`);

    node.status({ fill: "green", shape: "dot", text: `Flag ${determinedFlag}: Updated ${changedSummary.join(" ")}` });

    return [
        {
            payload: {
                flag: determinedFlag,
                modifiedBlock1: modifiedB1,
                modifiedBlock2: modifiedB2,
                modifiedBlock3: modifiedB3,
                currentBlock1: regsBlock1,
                currentBlock2: regsBlock2,
                currentBlock3: regsBlock3
            },
            flag: determinedFlag
        },
        null
    ];
}

return null;

// =========================================================================
// CONFIGURATION REGISTER CHANGE DETECTOR & LOGGER
// Supports:
// - FC 03 Read Responses: [01, 03, B4(180), ...]
// - FC 16 Write Requests: [01, 10, Addr(2), Qty(2), ByteCount(180), ...]
// Mapping:
// - Reg 1001..1090 (3, 233) -> FLAG 2 (Block 1)
// - Reg 1091..1180 (4, 67)  -> FLAG 4 (Block 2)
// - Reg 1181..1270 (4, 157) -> FLAG 8 (Block 3)
// =========================================================================

// Handle manual baseline reset trigger
if (msg.payload === "reset_baseline" || msg.payload === "reset") {
    context.set("last_1001", null);
    context.set("last_1091", null);
    context.set("last_1181", null);
    node.status({ fill: "blue", shape: "dot", text: "Baselines reset: Next packets will be stored as new baselines" });
    return null;
}

let buf = msg.payload;
if (!Buffer.isBuffer(buf)) {
    if (Array.isArray(buf)) {
        buf = Buffer.from(buf);
    } else {
        return null;
    }
}

// Safety check: must target Slave 1
if (buf.length < 5 || buf[0] !== 1) {
    return null;
}

const fc = buf[1];
let startReg = null;
let dataOffset = null;
let msgTypeDesc = "";

// -------------------------------------------------------------------------
// Case 1: FC 03 Read Response: [01, 03, B4(180), <180 data bytes>, CRC]
// -------------------------------------------------------------------------
if (fc === 3 && buf[2] === 180 && buf.length >= 183) {
    dataOffset = 3;
    msgTypeDesc = "FC 03 Response";

    // Confirmation at payload offset 18 (byte 21 in buffer)
    const conf = buf.readUInt16BE(21);
    if (conf === 1001) {
        startReg = 1001; // Flag 2
    } else if (conf === 1091) {
        startReg = 1091; // Flag 4
    } else if (conf === 1181) {
        startReg = 1181; // Flag 8
    } else {
        const lastReq = flow.get("last_requested_config_block");
        startReg = (lastReq === 1091 || lastReq === 1181) ? lastReq : 1001;
    }
}
// -------------------------------------------------------------------------
// Case 2: FC 16 Write Multiple: [01, 10, AddrHi, AddrLo, QtyHi, QtyLo, ByteCount(180), <180 data bytes>, CRC]
// -------------------------------------------------------------------------
else if (fc === 16 && buf.length >= 187 && buf[6] === 180) {
    let addr = buf.readUInt16BE(2);
    if (addr === 1001 || addr === 1091 || addr === 1181) {
        startReg = addr;
    } else if (buf.length >= 27) {
        const conf = buf.readUInt16BE(25); // Offset 18 in payload (7 + 18 = 25)
        if (conf === 1001 || conf === 1091 || conf === 1181) {
            startReg = conf;
        }
    }
    if (startReg) {
        dataOffset = 7;
        msgTypeDesc = "FC 16 Write";
    }
}

if (!startReg || dataOffset === null) {
    return null;
}

// Block identification & Flag assignment:
// - Start Reg 1001 (3, 233) -> Block 1 / FLAG 2
// - Start Reg 1091 (4, 67)  -> Block 2 / FLAG 4
// - Start Reg 1181 (4, 157) -> Block 3 / FLAG 8
const assignedFlag = (startReg === 1001) ? 2 : ((startReg === 1091) ? 4 : 8);
const blockNum = (startReg === 1001) ? 1 : ((startReg === 1091) ? 2 : 3);
const blockName = `Block ${blockNum} (Reg ${startReg}-${startReg + 89} / Flag ${assignedFlag})`;

// -------------------------------------------------------------------------
// 2. Parse all 90 registers (int16 Big-Endian)
// -------------------------------------------------------------------------
const currentRegs = {};
for (let i = 0; i < 90; i++) {
    const regNum = startReg + i;
    currentRegs[regNum] = buf.readInt16BE(dataOffset + i * 2);
}

// Update memory in flow context as well
const flowKey = "lcd_config_registers_block" + blockNum;
const existingFlowRegs = flow.get(flowKey) || {};
flow.set(flowKey, Object.assign({}, existingFlowRegs, currentRegs));

// Track seen blocks for initialization
let seen = flow.get("lcd_blocks_seen") || {};
seen[startReg] = true;
flow.set("lcd_blocks_seen", seen);
if (seen[1001] && seen[1091] && seen[1181]) {
    flow.set("lcd_config_initialized", true);
    flow.set("lcd_sync_status", "initialized");
}

// -------------------------------------------------------------------------
// 3. Format clean timestamp: YYYY-MM-DD HH:mm:ss
// -------------------------------------------------------------------------
const now = new Date();
const timeStamp = now.getFullYear() + "-" +
    ("0" + (now.getMonth() + 1)).slice(-2) + "-" +
    ("0" + now.getDate()).slice(-2) + " " +
    ("0" + now.getHours()).slice(-2) + ":" +
    ("0" + now.getMinutes()).slice(-2) + ":" +
    ("0" + now.getSeconds()).slice(-2);

// -------------------------------------------------------------------------
// 4. Compare with last stored snapshot for this specific block
// -------------------------------------------------------------------------
const lastKey = "last_" + startReg;
const lastRegs = context.get(lastKey);

// CASE A: Initial Snapshot (First time this block is seen)
if (!lastRegs) {
    context.set(lastKey, currentRegs);

    const nonZeros = [];
    for (let r = startReg; r < startReg + 90; r++) {
        if (currentRegs[r] !== 0) {
            nonZeros.push(`Reg ${r}=${currentRegs[r]}`);
        }
    }

    const baselineText = `${timeStamp} | [BASELINE STORED] ${blockName} via ${msgTypeDesc} (${nonZeros.length} non-zero): ${nonZeros.join(", ")}`;
    node.status({ fill: "blue", shape: "dot", text: `Baseline stored: Block ${blockNum} (Flag ${assignedFlag})` });

    msg.payload = baselineText;
    msg.event = "baseline_stored";
    msg.block = startReg;
    msg.flag = assignedFlag;
    msg.msgType = msgTypeDesc;
    msg.registers = currentRegs;
    return msg;
}

// CASE B: Subsequent Snapshot (Detect changed registers)
const diffs = [];
for (let i = 0; i < 90; i++) {
    const regNum = startReg + i;
    const oldVal = lastRegs[regNum];
    const newVal = currentRegs[regNum];

    if (oldVal !== newVal) {
        const diffVal = newVal - oldVal;
        const diffStr = diffVal > 0 ? `+${diffVal}` : `${diffVal}`;
        const oldHex = "0x" + (oldVal & 0xFFFF).toString(16).toUpperCase().padStart(4, "0");
        const newHex = "0x" + (newVal & 0xFFFF).toString(16).toUpperCase().padStart(4, "0");

        diffs.push({
            register: regNum,
            oldValue: oldVal,
            newValue: newVal,
            diff: diffVal,
            diffString: diffStr,
            oldHex: oldHex,
            newHex: newHex,
            summary: `Reg ${regNum}: ${oldVal} -> ${newVal} (Diff: ${diffStr} | Hex: ${oldHex}->${newHex})`
        });
    }
}

// Save current state as latest
context.set(lastKey, currentRegs);

// If no registers changed, do not log (avoids spamming log file)
if (diffs.length === 0) {
    return null;
}

// -------------------------------------------------------------------------
// 5. Construct log line for file & debug output
// -------------------------------------------------------------------------
const diffSummaries = diffs.map(d => d.summary).join(" | ");
const logLine = `${timeStamp} | [CONFIG CHANGED] ${blockName} via ${msgTypeDesc} [${diffs.length} change(s)]: ${diffSummaries}`;

const changedRegNumbers = diffs.map(d => `Reg ${d.register} (${d.oldValue}->${d.newValue})`).join(", ");
node.status({ fill: "red", shape: "dot", text: `CHANGED: ${changedRegNumbers}` });

msg.payload = logLine;
msg.event = "config_changed";
msg.block = startReg;
msg.flag = assignedFlag;
msg.msgType = msgTypeDesc;
msg.diffs = diffs;
msg.registers = currentRegs;

return msg;

// --- Process incoming configuration change from Home Assistant ---
// Topic format: nodered/heatpump/nodered_heatpump_001/config/<reg>/set
// Payload: "ON", "OFF", "Heating", "50.0", "52", etc.
const topic = msg.topic || "";
const match = topic.match(/\/config\/(\d+)\/set$/);

if (!match) {
    node.warn(`Invalid HA config set topic: ${topic}`);
    return null;
}

const reg = parseInt(match[1], 10);
const registry = flow.get("hp_config_registry") || {};
const def = registry[reg];

if (!def) {
    node.warn(`Received command for unmapped register: ${reg}`);
    return null;
}

// Safety guard: Must be initialized via Flag 128
const isInitialized = flow.get("lcd_config_initialized") === true;
if (!isInitialized) {
    node.warn(`Change for Reg ${reg} blocked: Parameters not read out via Flag 128 yet!`);
    node.status({ fill: "red", shape: "ring", text: `Blocked Reg ${reg}: wait Flag 128` });
    return null;
}

const rawPayload = (msg.payload !== undefined && msg.payload !== null) ? msg.payload.toString().trim() : "";
let rawVal = 0;
let displayVal = rawPayload;

if (def.component === "switch") {
    const upper = rawPayload.toUpperCase();
    if (upper === "ON" || upper === "1" || upper === "TRUE") {
        rawVal = 1;
        displayVal = "ON";
    } else if (upper === "OFF" || upper === "0" || upper === "FALSE") {
        rawVal = 0;
        displayVal = "OFF";
    } else {
        node.warn(`Invalid switch payload for Reg ${reg} (${def.key}): "${rawPayload}"`);
        return null;
    }
} else if (def.component === "select") {
    const options = def.options || [];
    const optIdx = options.findIndex(o => o.toLowerCase() === rawPayload.toLowerCase());
    if (optIdx !== -1) {
        rawVal = optIdx;
        displayVal = options[optIdx];
    } else {
        const parsedIdx = parseInt(rawPayload, 10);
        if (!isNaN(parsedIdx) && parsedIdx >= 0 && parsedIdx < options.length) {
            rawVal = parsedIdx;
            displayVal = options[parsedIdx];
        } else {
            node.warn(`Invalid select payload for Reg ${reg} (${def.key}): "${rawPayload}". Options: ${options.join(", ")}`);
            return null;
        }
    }
} else {
    // Number component (default)
    let userVal = parseFloat(rawPayload);
    if (isNaN(userVal)) {
        node.warn(`Invalid numeric payload for Reg ${reg} (${def.key}): "${rawPayload}"`);
        return null;
    }

    // Clamp to configured min/max
    if (def.min !== undefined && userVal < def.min) userVal = def.min;
    if (def.max !== undefined && userVal > def.max) userVal = def.max;

    // Convert to raw Modbus register integer
    const scale = def.scale || 1;
    rawVal = Math.round(userVal / scale);
    displayVal = userVal;
}

// Map register to appropriate Flag / Block:
// - Block 1: Reg 1001..1090 -> Flag 2
// - Block 2: Reg 1091..1180 -> Flag 4
// - Block 3: Reg 1181..1270 -> Flag 8
let determinedFlag = 2;
if (reg >= 1001 && reg <= 1090) {
    determinedFlag = 2;
} else if (reg >= 1091 && reg <= 1180) {
    determinedFlag = 4;
} else if (reg >= 1181 && reg <= 1270) {
    determinedFlag = 8;
}

node.status({ fill: "green", shape: "dot", text: `Set Reg ${reg} (${def.key}) = ${displayVal} (Raw: ${rawVal}, Flag: ${determinedFlag})` });

// Pass to lcd_config_manager_01
return {
    payload: {
        [reg]: rawVal
    },
    flag: determinedFlag,
    source: "homeassistant",
    userValue: displayVal,
    register: reg
};

// --- Publish Heat Pump Configuration Registers to MQTT State ---
const baseTopic = "nodered/heatpump";
const deviceIdentifier = "nodered_heatpump_001";
const configStateTopic = `${baseTopic}/${deviceIdentifier}/config_state`;

// Ordered list from flow context to guarantee logical priority order (all 109 parameters)
const list = flow.get("hp_config_list") || [];

// Check if configuration has been read out from Master via Flag 128
const isInit = flow.get("lcd_config_initialized") === true;
if (!isInit) {
    node.status({ fill: "yellow", shape: "ring", text: "Waiting for Flag 128 init before publishing" });
    return null;
}

const b1 = flow.get("lcd_config_registers_block1") || {};
const b2 = flow.get("lcd_config_registers_block2") || {};
const b3 = flow.get("lcd_config_registers_block3") || {};

const statePayload = {};
let count = 0;

for (const def of list) {
    const reg = def.reg;
    let raw = null;
    if (reg >= 1001 && reg <= 1090) {
        raw = b1[reg];
    } else if (reg >= 1091 && reg <= 1180) {
        raw = b2[reg];
    } else if (reg >= 1181 && reg <= 1270) {
        raw = b3[reg];
    }

    if (raw !== undefined && raw !== null) {
        if (def.component === "switch") {
            const isStateOn = (raw === 1 || raw === "1" || raw === true);
            const stateStr = isStateOn ? "ON" : "OFF";
            statePayload[def.key] = stateStr;
            statePayload[def.key + "_num"] = isStateOn ? 1 : 0;
        } else if (def.component === "select") {
            const options = def.options || [];
            const optName = options[raw] !== undefined ? options[raw] : ("Option " + raw);
            statePayload[def.key] = raw;
            statePayload[def.key + "_name"] = optName;
        } else {
            // Number component
            const scale = def.scale || 1;
            const scaledVal = parseFloat((raw * scale).toFixed(2));
            statePayload[def.key] = scaledVal;
        }
        count++;
    }
}

if (count === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "No registers loaded yet" });
    return null;
}

node.status({ fill: "green", shape: "dot", text: `Published ${count} config values to HA` });

return {
    topic: configStateTopic,
    payload: JSON.stringify(statePayload),
    retain: true
};
